/* eslint-disable @next/next/no-img-element */
/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";

import PageShell from "@vibaar/ui/PageShell";
import Header from "@vibaar/ui/common/Header";
import VendorNav from "@/features/storefront/VendorNav";
import ChatList from "@/features/chat/ChatList";
import { useRouter } from "next/navigation";
import useAuthStore from "@/store/authStore";
import Button from "@vibaar/ui/common/Button";

export default function Inbox() {
  const router = useRouter();
  const { user } = useAuthStore();
  // The former "Alerts" tab was five hardcoded mock rows behind a Sort bar
  // whose every handler was a no-op — placeholder UI shown to real buyers.
  // Notifications are a separate, real system at /notification (reached from
  // the profile bell), so the inbox is the messages list and nothing else.
  const messagesTab = (
    <ChatList onSelect={(c) => router.push(`/inbox/message/${c.id}`)} />
  );

  return (
    <PageShell
      header={
        <Header
          onBack={() => router.back()}
          title="Inbox"
        />
      }>
      {!user ? (
        <div className="flex flex-col items-center justify-center px-8 py-16 text-center">
          <EmptyMessage />
          <p className="text-sm font-medium text-foreground-secondary mt-4">
            Sign in to see your inbox
          </p>
          <p className="text-foreground-muted text-caption mt-2 w-[80%]">
            Your alerts and messages appear here once you sign in.
          </p>
          <div className="mt-6 w-full max-w-[220px]">
            <Button onClick={() => router.push("/signin")}>Sign in</Button>
          </div>
        </div>
      ) : (
        <>
          {messagesTab}
          <VendorNav />
        </>
      )}
    </PageShell>
  );
}

